import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns CSV string with header', () => {
  const result = exportCsv([]);

  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv exports a single issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);

  assert(csv.includes('Northwind Studio'));
  assert(csv.includes('INV-2025-0001'));
  assert(csv.includes('2025-01-15'));
  assert(csv.includes('issued'));
  assert(csv.includes('9025.00')); // subtotal with gold tier discount
  assert(csv.includes('10920.00')); // total
});

test('exportCsv formats amounts as plain euros with 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];

  // Check that amounts use dot decimal separator and have 2 decimals
  assert(dataLine.match(/\d+\.\d{2}/)); // e.g., 9025.00
  // Check no currency signs
  assert(!dataLine.includes('€'));
  assert(!dataLine.includes('$'));
});

test('exportCsv includes dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);

  assert(csv.includes('2025-01-29')); // due date for NET14
});

test('exportCsv escapes customer name with comma', () => {
  const inv = createInvoice({
    customerId: 'C-004', // Smith, Jones & Partners
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);

  // Customer name contains a comma, should be quoted
  assert(csv.includes('"Smith, Jones & Partners"'));
});

test('exportCsv escapes customer name with double quote', () => {
  const inv = createInvoice({
    customerId: 'C-006', // Marlow "The Print Shop"
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);

  // Customer name contains a quote, should be escaped
  assert(csv.includes('"Marlow ""The Print Shop"""'));
});

test('exportCsv includes discount field', () => {
  const inv = createInvoice({
    customerId: 'C-001', // gold tier gets 5% discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');

  // discount field (5% of 9500 = 475)
  assert.equal(fields[6], '475.00');
});

test('exportCsv includes VAT field', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');

  // VAT field should be non-zero (21% VAT)
  assert(fields[7] !== '0.00');
});

test('exportCsv calculates due correctly for partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const payment = recordPayment(issued.value, { amount: 5000, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const csv = exportCsv([payment.value]);

  // Total is 10920, paid 5000, due is 5920
  assert(csv.includes('5920.00'));
});

test('exportCsv handles multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-16',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2025-0001']);
  assert.equal(issued2.ok, true);

  const csv = exportCsv([issued1.value, issued2.value]);
  const lines = csv.split('\n');

  // Header + 2 data lines + empty line at end
  assert.equal(lines.length, 4);
  assert(lines[1].includes('INV-2025-0001'));
  assert(lines[2].includes('INV-2025-0002'));
});

test('exportCsv maintains invoice order', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-02',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2025-0001']);
  assert.equal(issued2.ok, true);

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-03',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv3.ok, true);
  const issued3 = issueInvoice(inv3.value, ['INV-2025-0001', 'INV-2025-0002']);
  assert.equal(issued3.ok, true);

  const csv = exportCsv([issued2.value, issued3.value, issued1.value]);
  const lines = csv.split('\n');

  assert.equal(lines[1].split(',')[0], 'INV-2025-0002');
  assert.equal(lines[2].split(',')[0], 'INV-2025-0003');
  assert.equal(lines[3].split(',')[0], 'INV-2025-0001');
});

test('exportCsv CSV lines end with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);

  assert(csv.endsWith('\n'));
});

test('exportCsv includes draft invoice with proper status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);

  const csv = exportCsv([inv.value]);

  assert(csv.includes('draft'));
});

test('exportCsv handles invoice with no number (draft)', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);

  const csv = exportCsv([inv.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');

  // number field should be empty
  assert.equal(fields[0], '');
});

test('exportCsv with 0% VAT product', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');

  // VAT should be 0.00
  assert.equal(fields[7], '0.00');
});

test('exportCsv with multiple lines and mixed VAT', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 10 }, // 9% VAT
    ],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);

  assert(csv.includes('issued'));
  // Should have combined subtotal and VAT
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert(fields[5]); // subtotal
  assert(fields[7]); // VAT
});

test('exportCsv with very large amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'BRAND-BOOK', qty: 100 }, // 245000 * 100
    ],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);

  // Should have proper formatting with many digits
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert(dataLine.match(/\d{6,}\.\d{2}/)); // Many digits before decimal
});

test('exportCsv properly parses CSV with quoted fields', () => {
  const inv = createInvoice({
    customerId: 'C-004', // Smith, Jones & Partners (has comma)
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];

  // The customer field should be quoted and properly escaped
  // Manual parsing to verify
  const match = dataLine.match(/"Smith, Jones & Partners"/);
  assert(match, 'Customer name with comma should be properly quoted');
});

